#include <stdio.h>

struct Point {
    int x;
    int y;
};

int manhattan_distance(struct Point p1, struct Point p2) {
    int dx = p1.x - p2.x;
    int dy = p1.y - p2.y;
    if (dx < 0) dx = -dx;
    if (dy < 0) dy = -dy;
    return dx + dy;
}

int main() {
    struct Point a = {0, 0};
    struct Point b = {3, 4};
    int dist = manhattan_distance(a, b);
    printf("Dist: %d\n", dist);
    return 0;
}

