void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int t = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = t;
            }
        }
    }
}

int main() {
    int a[] = {5, 1, 4, 2, 8};
    bubble_sort(a, 5);
    printf("Sorted first: %d\n", a[0]);
    return 0;
}

