#include <stdio.h>

long long power(int base, int exp) {
    long long result = 1;
    long long b = base;
    int e = exp;
    while (e > 0) {
        if (e % 2 == 1) {
            result = result * b;
        }
        b = b * b;
        e = e / 2;
    }
    return result;
}

int main() {
    long long ans = power(2, 10);
    printf("2^10 = %lld\n", ans);
    return 0;
}

