#include <stdio.h>

int binary_search(const int arr[], int size, int key) {
    int low = 0;
    int high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == key) {
            return mid;
        } else if (arr[mid] < key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

int main() {
    int sorted_nums[] = {2, 5, 8, 12, 16, 23, 38, 56};
    int pos = binary_search(sorted_nums, 8, 23);
    printf("Index: %d\n", pos);
    return 0;
}

