#include <iostream>

class BankAccount {
private:
    double balance;
public:
    BankAccount(double initial) : balance(initial >= 0 ? initial : 0) {}
    bool deposit(double amount) {
        if (amount <= 0) return false;
        balance += amount;
        return true;
    }
    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        return true;
    }
    double get_balance() const {
        return balance;
    }
};

int main() {
    BankAccount acc(100.0);
    acc.deposit(50.0);
    acc.withdraw(30.0);
    std::cout << "Balance: " << acc.get_balance() << std::endl;
    return 0;
}

