def memoize(fn):
    cache = {}
    def inner(arg):
        if arg not in cache:
            cache[arg] = fn(arg)
        return cache[arg]
    return inner

@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    print(f'Fib 10: {fib(10)}')

